from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, Preformatted
from reportlab.lib import colors
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4
from pathlib import Path
out=Path('output/pdf/StegoVerify_Start_Location_Explained.pdf')
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='TitleX',fontName='Helvetica-Bold',fontSize=23,leading=27,textColor=colors.HexColor('#16324f'),spaceAfter=12))
styles.add(ParagraphStyle(name='Deck',fontSize=11,leading=16,textColor=colors.HexColor('#526477'),spaceAfter=17))
styles.add(ParagraphStyle(name='HeadX',fontName='Helvetica-Bold',fontSize=14,leading=18,textColor=colors.HexColor('#16324f'),spaceBefore=14,spaceAfter=8))
styles.add(ParagraphStyle(name='BodyX',fontSize=10.5,leading=15,spaceAfter=9))
styles.add(ParagraphStyle(name='CellX',fontSize=9.5,leading=13,spaceAfter=0))
styles.add(ParagraphStyle(name='CodeX',fontName='Courier',fontSize=9,leading=14,backColor=colors.HexColor('#f0f4f8'),borderPadding=10,spaceBefore=6,spaceAfter=14))
story=[]
def p(t,style='BodyX'): story.append(Paragraph(t,styles[style]))
def h(t): p(t,'HeadX')
def code(t): story.append(Preformatted(t,styles['CodeX']))
def table(rows,widths):
 t=Table([[Paragraph(c,styles['CellX']) for c in r] for r in rows],colWidths=widths,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e4edf5')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),8),('LINEBELOW',(0,0),(-1,-1),0.4,colors.HexColor('#d3dee8'))]))
 story.append(t); story.append(Spacer(1,10))
def footer(c,d):
 c.setFont('Helvetica',8); c.setFillColor(colors.HexColor('#66788a'))
 c.drawString(46,29,'StegoVerify | FR7 and FR13 | Team explanation')
 c.drawRightString(A4[0]-46,29,str(d.page))
p('How StegoVerify finds the payload','TitleX')
p('A team guide to the start calculation, masked hash and Wrong Start Location verdict','Deck')
p('<b>The main idea:</b> the decoder repeats the sender\'s calculation using values that remain the same after embedding. It then checks whether a valid container exists at the calculated position.')
h('1  What goes into the calculation')
table([['<b>Input</b>','<b>Meaning</b>'],['Shared secret','Text known by both parties. It is the HMAC key, separate from the private/public keys used for digital signatures.'],['Cover type','The label image or audio. The label is included in the calculation; it is not itself converted into units.'],['Masked hash','A fingerprint calculated after ignoring the bits used for embedding.'],['n','The selected LSB depth, from 1 to 8. If n = 2, embedding uses the lowest two bits of each unit.'],['Number of units N','The number of embedding positions. An RGB image has one unit per R, G or B channel byte. For WAV audio, a unit is the lowest byte of each channel sample.']],[120,383])
code('HMAC key  = shared secret\nHMAC data = fixed label + cover type + masked hash + n\n\nstart unit = integer(HMAC-SHA256 result) mod N')
p('The fixed label in the code is <b>SVFY-start</b>. The modulo operation maps the large HMAC result to a valid unit index from <b>0 to N - 1</b>.')
p('<b>Random-looking, but repeatable:</b> the same inputs always produce the same start. Re-encoding the same cover with the same secret and LSB depth does not, by itself, move the start.')
h('The three different secrets')
p('<b>Shared secret:</b> derives the start location. <b>Encryption passphrase:</b> protects the message contents. <b>Signing private key:</b> creates the digital signature; the corresponding public key checks it.')
p('Code references: stegoverify/startloc.py, covers.py, engine.py and payload.py. Companion reference: StegoVerify Start Location and Innovation PDF, sections 1.3 and 1.4.','CellX')
story.append(PageBreak())
p('Why the decoder gets the same location','TitleX')
h('2  Ignore the bits that embedding changes')
p('Embedding changes the file, so hashing the complete original file and complete stego file would normally give different results. The masked hash solves this by ignoring the lowest n bits of every embedding unit.')
p('For example, select <b>n = 2</b>. Only the last two bits of this unit are replaced:')
code('Original unit:       101101 01\nAfter embedding:     101101 10\n                     ------ --\n                     same   replaced')
p('Before calculating the fingerprint, temporarily set the lowest two bits to zero:')
code('Original, masked:    101101 00\nStego, masked:       101101 00\n\nResult: the masked values are identical.')
p('This happens across every embedding unit. The image hash also includes dimensions and channel information; the audio hash includes format information and preserves the unmodified higher sample bytes.')
p('<b>Masking does not erase the saved payload.</b> The program hashes a temporary representation. The stego file and its embedded message remain intact.')
h('3  Both parties repeat the same calculation')
table([['<b>Party A - sender</b>','<b>Party B - receiver</b>'],['Has the original cover.','Has the received stego file.'],['Masks the lowest n bits and gets fingerprint H.','Masks the same lowest n bits and gets the same H.'],['Uses the secret, cover type, H and n in HMAC.','Uses the same secret, cover type, H and n in HMAC.'],['Takes the result modulo N and embeds from that unit.','Takes the result modulo the same N and reads from that unit.']],[251.5,251.5])
p('<b>Party B does not need the original cover or a transmitted coordinate.</b> It reconstructs the start from the received file and shared settings. In manual mode, however, the chosen coordinate must be shared separately.')
p('This equality assumes the cover has only undergone the embedding process and both parties use the same n. Subsequent content changes can change the masked hash. The verifier can try LSB depths 1 to 8 when set to auto.')
story.append(PageBreak())
p('Finding the header and diagnosing failure','TitleX')
h('4  Check what is at the calculated position')
p('The hidden container starts with a <b>16-byte header</b>: an SVFY marker, version, flags and section lengths. SVFY is a recognisable start label encoded into the LSBs.')
p('The decoder reads the selected LSBs from successive units at the expected start, rebuilds the header, and checks the marker, version and sensible lengths. Finding a header means it has found a candidate container. Signature and integrity checks still follow.')
p('In <b>_locate()</b>, <b>True</b> means "found at the expected position". <b>False</b> means "found elsewhere by scanning". Neither value by itself means the file is authentic.')
h('5  What a wrong secret does')
code('Illustrative positions, not actual demo results:\nCorrect secret -> payload starts at unit 4,200\nWrong secret   -> expected start is unit 900\nRead at 900    -> no valid header\nDiagnostic scan finds the header at 4,200')
p('With <b>scan whole cover if not at expected location</b> enabled, the decoder searches for the marker elsewhere. It checks the recovered container before deciding the verdict:')
table([['<b>What is found</b>','<b>What happens</b>'],['Valid header at the expected position','Continue verification; potentially Authentic.'],['Container elsewhere; signature and integrity checks pass','Wrong Start Location. The app returns before opening or displaying the message.'],['Container elsewhere; signature or integrity checks fail','Signature Invalid or Tampered, depending on the failure.'],['No valid header found','Payload Missing.']],[247,256])
p('<b>Keep diagnostic scanning enabled for the wrong-secret demo.</b> Without it, the decoder may report Payload Missing because it does not search beyond the expected position.')
p('<b>Security limitation:</b> an attacker can also scan for the visible marker. The application withholding a message does not prevent a separate extraction tool. Encryption protects confidentiality; the signature and hashes support authenticity and integrity.')
h('Short presentation script')
p('"The receiver gets the same start because we ignore the bits that embedding changes when calculating the fingerprint. Both files therefore have the same masked hash. With the same secret and settings, both parties calculate the same position. The decoder checks for our SVFY header there. If scanning finds a genuine, intact payload somewhere else, the application reports Wrong Start Location and does not display the message."')
SimpleDocTemplate(str(out),pagesize=A4,rightMargin=46,leftMargin=46,topMargin=40,bottomMargin=46,title='StegoVerify Start Location Explained',author='StegoVerify Team').build(story,onFirstPage=footer,onLaterPages=footer)
from pypdf import PdfReader
print(str(out.resolve()))
print('Pages:',len(PdfReader(out).pages))
